"""Round-5 coverage additions, written from a topic-gap analysis (not from held-out wording). MySQL 8.0.28 syntax only.
SELECT entries: `sql` and `alt` must return identical result sets (checked by build_bank.py).
DML/DDL entries: `sql` and `alt` are scripts; build_bank.py runs them, then `check` (a SELECT) reads the resulting state.
  mode 'rollback' = pure DML inside START TRANSACTION ... ROLLBACK; mode 'ddl' = DDL auto-commits, so `cleanup` undoes it."""

REV = "line.Quantity*line.`Unit Price`*(1-line.Discount)"
ORDER_TOTALS = ("order_totals AS (SELECT ord.`Order ID` AS order_id, ord.`Employee ID` AS employee_id, ord.`Customer ID` AS customer_id, SUM("
                + REV + ") AS total FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` GROUP BY ord.`Order ID`, ord.`Employee ID`, ord.`Customer ID`)")
MONTHLY = ("monthly AS (SELECT DATE_FORMAT(ord.`Order Date`,'%Y-%m') AS month_label, SUM(" + REV + ") AS revenue FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` "
           "WHERE ord.`Order Date` >= '2006-01-01' AND ord.`Order Date` < '2007-01-01' GROUP BY DATE_FORMAT(ord.`Order Date`,'%Y-%m'))")

def S(number, question, sql, alt, explanation, pattern, tags, techniques, cmp='set'):
    return dict(id='SQL4-%03d' % number, question=question, sql=sql, alt=alt, explanation=explanation, pattern=pattern,
                tags=tags.split('|'), techniques=techniques.split('|'), difficulty=4, cmp=cmp, mode=None, check=None, cleanup=None)

def D(number, question, sql, alt, check, cleanup, mode, explanation, pattern, tags, techniques):
    return dict(id='SQL4-%03d' % number, question=question, sql=sql, alt=alt, explanation=explanation, pattern=pattern,
                tags=tags.split('|'), techniques=techniques.split('|'), difficulty=3, cmp='ordered', mode=mode, check=check, cleanup=cleanup)

SQL4 = [
 S(1, "For each product category list the three most expensive products by List Price, breaking price ties by lower product ID; show category, product ID, name and List Price.",
   "SELECT Category, ID, `Product Name`, `List Price` FROM (SELECT Category, ID, `Product Name`, `List Price`, ROW_NUMBER() OVER (PARTITION BY Category ORDER BY `List Price` DESC, ID) AS position FROM products WHERE `List Price` IS NOT NULL) ranked WHERE position <= 3;",
   "SELECT p.Category, p.ID, p.`Product Name`, p.`List Price` FROM products p WHERE p.`List Price` IS NOT NULL AND (SELECT COUNT(*) FROM products q WHERE q.Category <=> p.Category AND q.`List Price` IS NOT NULL AND (q.`List Price` > p.`List Price` OR (q.`List Price` = p.`List Price` AND q.ID < p.ID))) < 3;",
   "ROW_NUMBER gives exactly three rows per category, so tied prices at the cut-off are separated by the ID tie-break (use RANK instead if all tied rows must stay). Products without a List Price are ignored. A category with fewer than three priced products returns all of them. The alternative counts strictly better products with the same tuple ordering.",
   'topn_rank', 'top n per group|category|list price|ties', 'ROW_NUMBER partition|correlated better-count'),
 S(2, "For each customer State/Province list the two customers with the most orders, breaking ties by lower customer ID; customers without orders count as zero orders.",
   "WITH counts AS (SELECT c.ID, c.Company, c.`State/Province` AS state, COUNT(o.`Order ID`) AS order_count FROM customers c LEFT JOIN orders o ON o.`Customer ID`=c.ID GROUP BY c.ID, c.Company, c.`State/Province`) SELECT state, ID, Company, order_count FROM (SELECT counts.*, ROW_NUMBER() OVER (PARTITION BY state ORDER BY order_count DESC, ID) AS position FROM counts) ranked WHERE position <= 2;",
   "WITH counts AS (SELECT c.ID, c.Company, c.`State/Province` AS state, COUNT(o.`Order ID`) AS order_count FROM customers c LEFT JOIN orders o ON o.`Customer ID`=c.ID GROUP BY c.ID, c.Company, c.`State/Province`) SELECT a.state, a.ID, a.Company, a.order_count FROM counts a WHERE (SELECT COUNT(*) FROM counts b WHERE b.state <=> a.state AND (b.order_count > a.order_count OR (b.order_count = a.order_count AND b.ID < a.ID))) < 2;",
   "COUNT(o.`Order ID`) counts only matched orders, so customers without orders have 0 and may still fill a slot in a state with few active customers. The ID tie-break makes the cut deterministic; states with one customer return one row.",
   'topn_rank', 'top n per group|state|customer|order count', 'ROW_NUMBER over aggregate|correlated rank count'),
 S(3, "For each employee find the order or orders with the highest discounted line total; keep tied orders and show employee ID, order ID and the total rounded to cents.",
   "WITH " + ORDER_TOTALS + " SELECT employee_id, order_id, ROUND(total,2) FROM (SELECT order_totals.*, RANK() OVER (PARTITION BY employee_id ORDER BY total DESC) AS position FROM order_totals WHERE employee_id IS NOT NULL) ranked WHERE position = 1;",
   "WITH " + ORDER_TOTALS + " SELECT t.employee_id, t.order_id, ROUND(t.total,2) FROM order_totals t WHERE t.employee_id IS NOT NULL AND t.total = (SELECT MAX(u.total) FROM order_totals u WHERE u.employee_id = t.employee_id);",
   "Order total = SUM(Quantity*Unit Price*(1-Discount)) over the order lines; shipping and taxes are excluded. RANK keeps every order tied at the maximum. Orders without lines have no total and cannot win. Employees with no orders do not appear.",
   'topn_rank', 'highest per group|employee|order total|ties', 'RANK partition|correlated MAX'),
 S(4, "For each quarter of 2006 find the product or products with the highest total quantity sold; keep ties and show quarter number, product ID, name and quantity.",
   "WITH quarterly AS (SELECT QUARTER(ord.`Order Date`) AS quarter_no, line.`Product ID` AS product_id, SUM(line.Quantity) AS quantity FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` WHERE ord.`Order Date` >= '2006-01-01' AND ord.`Order Date` < '2007-01-01' GROUP BY QUARTER(ord.`Order Date`), line.`Product ID`) SELECT q.quarter_no, q.product_id, p.`Product Name`, q.quantity FROM (SELECT quarterly.*, RANK() OVER (PARTITION BY quarter_no ORDER BY quantity DESC) AS position FROM quarterly) q JOIN products p ON p.ID = q.product_id WHERE q.position = 1;",
   "WITH quarterly AS (SELECT QUARTER(ord.`Order Date`) AS quarter_no, line.`Product ID` AS product_id, SUM(line.Quantity) AS quantity FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` WHERE ord.`Order Date` >= '2006-01-01' AND ord.`Order Date` < '2007-01-01' GROUP BY QUARTER(ord.`Order Date`), line.`Product ID`) SELECT q.quarter_no, q.product_id, p.`Product Name`, q.quantity FROM quarterly q JOIN products p ON p.ID = q.product_id WHERE q.quantity = (SELECT MAX(r.quantity) FROM quarterly r WHERE r.quarter_no = q.quarter_no);",
   "Best-selling means largest SUM(Quantity), not revenue. Quarters without any order do not appear (the data covers only January-June 2006). The date range is written as a half-open interval so an index on Order Date stays usable.",
   'topn_rank', 'best selling|quarter|quantity|ties', 'RANK partition by quarter|correlated MAX per quarter'),
 S(5, "Show each customer's percentage of the total discounted revenue of all orders, rounded to two decimals; include only customers with sales.",
   "WITH customer_sales AS (SELECT ord.`Customer ID` AS customer_id, SUM(" + REV + ") AS revenue FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` WHERE ord.`Customer ID` IS NOT NULL GROUP BY ord.`Customer ID`) SELECT customer_id, ROUND(revenue,2), ROUND(100*revenue/SUM(revenue) OVER (),2) FROM customer_sales;",
   "SELECT ord.`Customer ID`, ROUND(SUM(" + REV + "),2), ROUND(100*SUM(" + REV + ")/(SELECT SUM(l2.Quantity*l2.`Unit Price`*(1-l2.Discount)) FROM orders o2 JOIN `order details` l2 ON l2.`Order ID`=o2.`Order ID` WHERE o2.`Customer ID` IS NOT NULL),2) FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` WHERE ord.`Customer ID` IS NOT NULL GROUP BY ord.`Customer ID`;",
   "Percent of total = customer revenue / revenue of all orders with a customer, times 100. The denominator is fixed before filtering rows, so shares add up to about 100 (rounding). SUM(revenue) OVER () needs no grouping; the alternative uses a scalar subquery. A zero grand total would give NULL, not an error.",
   'computed', 'percentage of total|share|customer|revenue', 'window over aggregate|scalar subquery denominator'),
 S(6, "For every employee, including those with no orders, show the number of orders and the percentage of all orders they handled, rounded to two decimals.",
   "SELECT e.ID, COUNT(o.`Order ID`), ROUND(100*COUNT(o.`Order ID`)/SUM(COUNT(o.`Order ID`)) OVER (),2) FROM employees e LEFT JOIN orders o ON o.`Employee ID`=e.ID GROUP BY e.ID;",
   "SELECT e.ID, (SELECT COUNT(*) FROM orders o WHERE o.`Employee ID`=e.ID), ROUND(100*(SELECT COUNT(*) FROM orders o WHERE o.`Employee ID`=e.ID)/(SELECT COUNT(*) FROM orders WHERE `Employee ID` IN (SELECT ID FROM employees)),2) FROM employees e;",
   "LEFT JOIN keeps employees with zero orders (0 and 0.00). The denominator is orders that belong to some known employee; orders with a NULL or unknown employee are outside the 100 percent. COUNT(o.`Order ID`) ignores the unmatched NULL row.",
   'computed', 'percentage|share of orders|employee|left join', 'SUM window over COUNT|scalar subquery counts'),
 S(7, "For each employee give the percentage of their orders that have no Shipped Date, rounded to two decimals; employees without orders show NULL.",
   "SELECT e.ID, ROUND(100*SUM(o.`Shipped Date` IS NULL)/NULLIF(COUNT(o.`Order ID`),0),2) FROM employees e LEFT JOIN orders o ON o.`Employee ID`=e.ID GROUP BY e.ID;",
   "SELECT e.ID, ROUND(100*(SELECT COUNT(*) FROM orders o WHERE o.`Employee ID`=e.ID AND o.`Shipped Date` IS NULL)/NULLIF((SELECT COUNT(*) FROM orders o WHERE o.`Employee ID`=e.ID),0),2) FROM employees e;",
   "Unshipped means Shipped Date IS NULL. NULLIF turns a zero order count into NULL so division is safe instead of failing or returning a misleading 0. Employees without orders: the single NULL-extended row makes the numerator 1, so the denominator guard is what yields NULL.",
   'null_handling', 'percentage|null shipped date|unshipped|employee', 'boolean SUM with NULLIF|correlated counts'),
 S(8, "Which shipper or shippers have the highest total Shipping Fee over their orders? Keep ties, ignore orders without a shipper, and show shipper ID, company and the total.",
   "WITH fees AS (SELECT s.ID, s.Company, SUM(o.`Shipping Fee`) AS total FROM shippers s JOIN orders o ON o.`Shipper ID`=s.ID GROUP BY s.ID, s.Company) SELECT ID, Company, ROUND(total,2) FROM fees WHERE total = (SELECT MAX(total) FROM fees);",
   "SELECT ID, Company, ROUND(total,2) FROM (SELECT s.ID, s.Company, SUM(o.`Shipping Fee`) AS total, RANK() OVER (ORDER BY SUM(o.`Shipping Fee`) DESC) AS position FROM shippers s JOIN orders o ON o.`Shipper ID`=s.ID GROUP BY s.ID, s.Company) ranked WHERE position = 1;",
   "'Highest total' means SUM(Shipping Fee) per shipper, not the largest single fee. Orders with a NULL Shipper ID join nothing and are ignored; NULL fees add nothing. Tied shippers all appear.",
   'topn_rank', 'highest total|shipper|shipping fee|ties', 'HAVING-style equality to MAX|RANK over aggregate'),
 S(9, "For each month of 2006 that has orders, show the month (YYYY-MM), its discounted revenue and the cumulative revenue up to and including that month, rounded to cents.",
   "WITH " + MONTHLY + " SELECT month_label, ROUND(revenue,2), ROUND(SUM(revenue) OVER (ORDER BY month_label ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW),2) FROM monthly;",
   "WITH " + MONTHLY + " SELECT m.month_label, ROUND(m.revenue,2), ROUND((SELECT SUM(p.revenue) FROM monthly p WHERE p.month_label <= m.month_label),2) FROM monthly m;",
   "Running total = sum of monthly revenue from the first month through the current one. Months without orders have no row (use a calendar if they must appear). ROWS makes the frame explicit; with ties in the ordering column RANGE would add peers, but month labels are unique here.",
   'computed', 'running total|cumulative|month|revenue', 'SUM ROWS window|correlated prefix sum'),
 S(10, "Compute for each month with orders its discounted revenue and the average revenue over that month and up to two preceding observed months (a three-month moving average), rounded to two decimals.",
   "WITH " + MONTHLY + " SELECT month_label, ROUND(revenue,2), ROUND(AVG(revenue) OVER (ORDER BY month_label ROWS BETWEEN 2 PRECEDING AND CURRENT ROW),2) FROM monthly;",
   "WITH " + MONTHLY + ", numbered AS (SELECT month_label, revenue, CAST(ROW_NUMBER() OVER (ORDER BY month_label) AS SIGNED) AS seq FROM monthly) SELECT a.month_label, ROUND(a.revenue,2), ROUND(AVG(b.revenue),2) FROM numbered a JOIN numbered b ON b.seq BETWEEN a.seq-2 AND a.seq GROUP BY a.month_label, a.revenue, a.seq;",
   "Frames count observed rows, not calendar months: a missing month would silently stretch the window. The first two months average over fewer rows (1 and 2), which is the usual convention; filter them out if only full windows are wanted.",
   'computed', 'moving average|month|window frame|revenue', 'AVG sliding ROWS frame|sequence self join'),
 S(11, "For each month count the customers whose first order (earliest Order Date) falls in that month; show the month as YYYY-MM and the number of new customers.",
   "SELECT DATE_FORMAT(first_date,'%Y-%m') AS month_label, COUNT(*) FROM (SELECT `Customer ID`, MIN(`Order Date`) AS first_date FROM orders WHERE `Customer ID` IS NOT NULL GROUP BY `Customer ID`) firsts GROUP BY DATE_FORMAT(first_date,'%Y-%m');",
   "SELECT DATE_FORMAT(o.`Order Date`,'%Y-%m'), COUNT(*) FROM orders o WHERE o.`Customer ID` IS NOT NULL AND NOT EXISTS (SELECT 1 FROM orders p WHERE p.`Customer ID`=o.`Customer ID` AND (p.`Order Date` < o.`Order Date` OR (p.`Order Date` = o.`Order Date` AND p.`Order ID` < o.`Order ID`))) GROUP BY DATE_FORMAT(o.`Order Date`,'%Y-%m');",
   "A customer is 'new' in the month of their earliest order, counted once however many orders they place that day. Customers without orders are not new customers. The anti-join alternative marks the single first order per customer using (date, ID) as the tie-break.",
   'not_exists', 'new customers|first order|month|anti join', 'MIN per customer derived table|NOT EXISTS earlier order'),
 S(12, "List orders whose discounted line total is above the average discounted total of all orders; show order ID and total rounded to cents.",
   "WITH totals AS (SELECT line.`Order ID` AS order_id, SUM(" + REV + ") AS total FROM `order details` line JOIN orders ord ON ord.`Order ID`=line.`Order ID` GROUP BY line.`Order ID`) SELECT order_id, ROUND(total,2) FROM (SELECT totals.*, AVG(total) OVER () AS average_total FROM totals) x WHERE total > average_total;",
   "WITH totals AS (SELECT line.`Order ID` AS order_id, SUM(" + REV + ") AS total FROM `order details` line JOIN orders ord ON ord.`Order ID`=line.`Order ID` GROUP BY line.`Order ID`) SELECT order_id, ROUND(total,2) FROM totals WHERE total > (SELECT AVG(total) FROM totals);",
   "The average is the mean of per-order totals (orders with at least one line), not the mean line value. An aggregate cannot be compared inside WHERE directly, hence the derived total plus window or scalar subquery. Strictly above, so orders equal to the average are excluded.",
   'subquery', 'above average|order total|scalar subquery|window average', 'AVG OVER whole set|scalar subquery'),
 S(13, "List employees whose total discounted revenue is above the average total revenue per employee, averaging over employees who have sales; show employee ID and revenue.",
   "WITH employee_revenue AS (SELECT ord.`Employee ID` AS employee_id, SUM(" + REV + ") AS revenue FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` WHERE ord.`Employee ID` IS NOT NULL GROUP BY ord.`Employee ID`) SELECT employee_id, ROUND(revenue,2) FROM employee_revenue WHERE revenue > (SELECT AVG(revenue) FROM employee_revenue);",
   "SELECT ord.`Employee ID`, ROUND(SUM(" + REV + "),2) FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` WHERE ord.`Employee ID` IS NOT NULL GROUP BY ord.`Employee ID` HAVING SUM(" + REV + ") > (SELECT SUM(l2.Quantity*l2.`Unit Price`*(1-l2.Discount)) / COUNT(DISTINCT o2.`Employee ID`) FROM orders o2 JOIN `order details` l2 ON l2.`Order ID`=o2.`Order ID` WHERE o2.`Employee ID` IS NOT NULL);",
   "Interpretation: the benchmark is the average over employees with sales, so inactive employees do not lower it. If inactive employees must count as zero, divide by the employee count instead. The alternative derives the average as total revenue / number of distinct employees with sales.",
   'subquery', 'above average|employee revenue|having subquery|aggregate of aggregate', 'CTE with scalar AVG|HAVING with computed average'),
 S(14, "List customers who placed more orders than the average number of orders per customer, counting customers with no orders as zero; show customer ID, company and order count.",
   "SELECT ID, Company, order_count FROM (SELECT c.ID, c.Company, COUNT(o.`Order ID`) AS order_count, COUNT(*) OVER () AS customer_count, SUM(COUNT(o.`Order ID`)) OVER () AS order_total FROM customers c LEFT JOIN orders o ON o.`Customer ID`=c.ID GROUP BY c.ID, c.Company) x WHERE order_count*customer_count > order_total;",
   "SELECT c.ID, c.Company, COUNT(o.`Order ID`) FROM customers c LEFT JOIN orders o ON o.`Customer ID`=c.ID GROUP BY c.ID, c.Company HAVING COUNT(o.`Order ID`)*(SELECT COUNT(*) FROM customers) > (SELECT COUNT(*) FROM orders WHERE `Customer ID` IN (SELECT ID FROM customers));",
   "The mean orders per customer is total orders / total customers; comparing count*customers > orders avoids a rounded decimal average. Customers with no orders are in the denominator, which pulls the average down; averaging over active customers only would give a different answer.",
   'subquery', 'above average|orders per customer|left join|exact comparison', 'window over grouped counts|HAVING with scalar totals'),
 S(15, "List products whose Reorder Level is above the quantity currently in stock, where stock is purchases minus every other movement type in the inventory ledger (missing movements mean 0); show ID, name, reorder level and stock.",
   "SELECT p.ID, p.`Product Name`, p.`Reorder Level`, COALESCE(SUM(CASE WHEN t.`Transaction Type`=1 THEN t.Quantity ELSE -t.Quantity END),0) AS stock FROM products p LEFT JOIN `inventory transactions` t ON t.`Product ID`=p.ID GROUP BY p.ID, p.`Product Name`, p.`Reorder Level` HAVING p.`Reorder Level` > stock;",
   "SELECT p.ID, p.`Product Name`, p.`Reorder Level`, s.stock FROM products p JOIN (SELECT p2.ID, COALESCE((SELECT SUM(IF(t.`Transaction Type`=1, t.Quantity, -t.Quantity)) FROM `inventory transactions` t WHERE t.`Product ID`=p2.ID),0) AS stock FROM products p2) s ON s.ID=p.ID WHERE p.`Reorder Level` > s.stock;",
   "Stock convention matches the lab stock report: type 1 (Purchased) adds, Sold, On Hold and Waste subtract. Products with no ledger rows have stock 0 and qualify whenever their Reorder Level is positive; a NULL Reorder Level never qualifies. State your own convention if the exam defines stock differently.",
   'cond_agg', 'reorder level|stock|inventory|having', 'conditional SUM with HAVING|derived scalar stock'),
 S(16, "Considering all orders in Order Date then Order ID sequence, return the smallest and the largest number of calendar days between consecutive orders.",
   "WITH ordered AS (SELECT `Order Date`, LAG(`Order Date`) OVER (ORDER BY `Order Date`, `Order ID`) AS previous_date FROM orders) SELECT MIN(DATEDIFF(`Order Date`, previous_date)), MAX(DATEDIFF(`Order Date`, previous_date)) FROM ordered WHERE previous_date IS NOT NULL;",
   "WITH numbered AS (SELECT `Order Date` AS order_date, ROW_NUMBER() OVER (ORDER BY `Order Date`, `Order ID`) AS n FROM orders) SELECT MIN(DATEDIFF(b.order_date, a.order_date)), MAX(DATEDIFF(b.order_date, a.order_date)) FROM numbered a JOIN numbered b ON b.n = a.n + 1;",
   "Gaps are between neighbours in the global (date, ID) sequence, so orders on the same day produce a gap of 0 and the minimum is usually 0. The first order has no predecessor and is excluded. DATEDIFF counts calendar days and ignores the time part.",
   'date', 'gap between orders|min max|lag|datediff', 'LAG then MIN/MAX|ROW_NUMBER self join'),
 S(17, "For each customer with at least two orders, return the average number of calendar days between their consecutive orders, rounded to two decimals.",
   "WITH gaps AS (SELECT `Customer ID` AS customer_id, DATEDIFF(`Order Date`, LAG(`Order Date`) OVER (PARTITION BY `Customer ID` ORDER BY `Order Date`, `Order ID`)) AS gap FROM orders WHERE `Customer ID` IS NOT NULL) SELECT customer_id, ROUND(AVG(gap),2) FROM gaps WHERE gap IS NOT NULL GROUP BY customer_id;",
   "SELECT `Customer ID`, ROUND(DATEDIFF(MAX(`Order Date`), MIN(`Order Date`)) / (COUNT(*) - 1), 2) FROM orders WHERE `Customer ID` IS NOT NULL GROUP BY `Customer ID` HAVING COUNT(*) >= 2;",
   "The consecutive gaps of one customer telescope: their sum is last date minus first date, so the average equals (last - first)/(orders - 1). The LAG version shows the gaps explicitly. Customers with a single order have no gap and are excluded.",
   'date', 'average gap|consecutive orders|customer|lag', 'LAG partition average|telescoping date range'),
 S(18, "Show one row per employee with the number of orders placed in 2005, 2006 and 2007 as three separate columns (a pivot); employees without orders show zeros.",
   "SELECT e.ID, COUNT(CASE WHEN YEAR(o.`Order Date`)=2005 THEN 1 END) AS y2005, COUNT(CASE WHEN YEAR(o.`Order Date`)=2006 THEN 1 END) AS y2006, COUNT(CASE WHEN YEAR(o.`Order Date`)=2007 THEN 1 END) AS y2007 FROM employees e LEFT JOIN orders o ON o.`Employee ID`=e.ID GROUP BY e.ID;",
   "SELECT e.ID, (SELECT COUNT(*) FROM orders o WHERE o.`Employee ID`=e.ID AND o.`Order Date` >= '2005-01-01' AND o.`Order Date` < '2006-01-01'), (SELECT COUNT(*) FROM orders o WHERE o.`Employee ID`=e.ID AND o.`Order Date` >= '2006-01-01' AND o.`Order Date` < '2007-01-01'), (SELECT COUNT(*) FROM orders o WHERE o.`Employee ID`=e.ID AND o.`Order Date` >= '2007-01-01' AND o.`Order Date` < '2008-01-01') FROM employees e;",
   "MySQL has no PIVOT: one CASE per output column inside COUNT (COUNT ignores the NULLs from non-matching CASE branches, so empty years give 0). The year list is fixed in the SQL; new years need new columns. SUM(condition) would return NULL, not 0, for an employee with no orders.",
   'cond_agg', 'pivot|orders per year|employee|conditional aggregation', 'COUNT(CASE) pivot|correlated scalar counts'),
 S(19, "For each shipper count the orders shipped within 7 days of the order date, the orders shipped later than 7 days, and the orders not yet shipped; include shippers with no orders.",
   "SELECT s.ID, COUNT(CASE WHEN DATEDIFF(o.`Shipped Date`, o.`Order Date`) <= 7 THEN 1 END), COUNT(CASE WHEN DATEDIFF(o.`Shipped Date`, o.`Order Date`) > 7 THEN 1 END), COUNT(CASE WHEN o.`Order ID` IS NOT NULL AND o.`Shipped Date` IS NULL THEN 1 END) FROM shippers s LEFT JOIN orders o ON o.`Shipper ID`=s.ID GROUP BY s.ID;",
   "SELECT s.ID, (SELECT COUNT(*) FROM orders o WHERE o.`Shipper ID`=s.ID AND DATEDIFF(o.`Shipped Date`, o.`Order Date`) <= 7), (SELECT COUNT(*) FROM orders o WHERE o.`Shipper ID`=s.ID AND DATEDIFF(o.`Shipped Date`, o.`Order Date`) > 7), (SELECT COUNT(*) FROM orders o WHERE o.`Shipper ID`=s.ID AND o.`Shipped Date` IS NULL) FROM shippers s;",
   "There is no required-date column, so 'on time' is interpreted as shipped within 7 calendar days of ordering (7 inclusive). Unshipped orders are a third bucket, not late: DATEDIFF with a NULL date is NULL and matches neither comparison. Orders without a shipper are not attributed to any shipper.",
   'cond_agg', 'on time vs late|shipper|shipping days|conditional aggregation', 'COUNT(CASE) buckets|correlated bucket counts'),
 S(20, "Find orders that contain at least one line with Quantity 50 or more and at least one line with Quantity below 10; return the order IDs.",
   "SELECT `Order ID` FROM `order details` GROUP BY `Order ID` HAVING SUM(Quantity >= 50) > 0 AND SUM(Quantity < 10) > 0;",
   "SELECT o.`Order ID` FROM orders o WHERE EXISTS (SELECT 1 FROM `order details` l WHERE l.`Order ID`=o.`Order ID` AND l.Quantity >= 50) AND EXISTS (SELECT 1 FROM `order details` l WHERE l.`Order ID`=o.`Order ID` AND l.Quantity < 10);",
   "Two conditions on different lines of the same order cannot be a single WHERE (no one line is both). Use conditional aggregation in HAVING or two EXISTS. The same shape answers 'orders with both a discounted and a non-discounted line' by changing the conditions to Discount > 0 and Discount = 0 (empty in this dump because every Discount is 0).",
   'group_having', 'both conditions|same order|different lines|having', 'HAVING with boolean sums|double EXISTS'),
 S(21, "For each employee compute the average number of order lines per order, rounded to two decimals; employees without orders show NULL.",
   "WITH order_lines AS (SELECT o.`Order ID` AS order_id, o.`Employee ID` AS employee_id, COUNT(l.ID) AS line_count FROM orders o LEFT JOIN `order details` l ON l.`Order ID`=o.`Order ID` GROUP BY o.`Order ID`, o.`Employee ID`) SELECT e.ID, ROUND(AVG(ol.line_count),2) FROM employees e LEFT JOIN order_lines ol ON ol.employee_id=e.ID GROUP BY e.ID;",
   "SELECT e.ID, ROUND(COUNT(l.ID)/NULLIF(COUNT(DISTINCT o.`Order ID`),0),2) FROM employees e LEFT JOIN orders o ON o.`Employee ID`=e.ID LEFT JOIN `order details` l ON l.`Order ID`=o.`Order ID` GROUP BY e.ID;",
   "An average of a count needs two levels: count lines per order first, then average per employee. The alternative uses total lines / distinct orders, which is equivalent because orders without lines still count once in the denominator. Employees with no orders give NULL, not 0.",
   'multi_agg', 'average lines per order|nested aggregate|employee', 'two-level aggregation|lines / distinct orders'),
 S(22, "Rank suppliers by total purchase value (quantity times unit cost over their purchase orders), highest first, equal totals sharing a rank; show rank, supplier ID, company and total.",
   "SELECT RANK() OVER (ORDER BY SUM(d.Quantity*d.`Unit Cost`) DESC), s.ID, s.Company, ROUND(SUM(d.Quantity*d.`Unit Cost`),2) FROM suppliers s JOIN `purchase orders` p ON p.`Supplier ID`=s.ID JOIN `purchase order details` d ON d.`Purchase Order ID`=p.`Purchase Order ID` GROUP BY s.ID, s.Company;",
   "WITH totals AS (SELECT s.ID, s.Company, SUM(d.Quantity*d.`Unit Cost`) AS total FROM suppliers s JOIN `purchase orders` p ON p.`Supplier ID`=s.ID JOIN `purchase order details` d ON d.`Purchase Order ID`=p.`Purchase Order ID` GROUP BY s.ID, s.Company) SELECT 1 + (SELECT COUNT(*) FROM totals u WHERE u.total > t.total), t.ID, t.Company, ROUND(t.total,2) FROM totals t;",
   "A window function can rank an aggregate directly because windows are evaluated after GROUP BY. RANK leaves gaps after ties (1,1,3); use DENSE_RANK for 1,1,2. Purchase value ignores receipt and payment status; suppliers without purchase orders are not ranked.",
   'topn_rank', 'rank|supplier|purchase value|window over aggregate', 'RANK over SUM|1 + count of higher totals'),
 S(23, "Rank employees by the number of different customers they served, highest first with no gaps after ties (dense rank); employees without orders get 0.",
   "SELECT DENSE_RANK() OVER (ORDER BY COUNT(DISTINCT o.`Customer ID`) DESC), e.ID, COUNT(DISTINCT o.`Customer ID`) FROM employees e LEFT JOIN orders o ON o.`Employee ID`=e.ID GROUP BY e.ID;",
   "WITH served AS (SELECT e.ID, (SELECT COUNT(DISTINCT o.`Customer ID`) FROM orders o WHERE o.`Employee ID`=e.ID) AS n FROM employees e) SELECT (SELECT COUNT(DISTINCT u.n) FROM served u WHERE u.n > s.n) + 1, s.ID, s.n FROM served s;",
   "COUNT(DISTINCT customer) counts customers once however many orders they placed. DENSE_RANK numbers distinct counts consecutively (1,1,2) whereas RANK would jump (1,1,3). The alternative counts the distinct higher values.",
   'topn_rank', 'dense rank|distinct customers|employee|window', 'DENSE_RANK over distinct count|count of distinct higher values'),
 S(24, "Compute the median discounted total over all orders that have at least one line (the average of the two middle totals when the count is even), rounded to cents.",
   "WITH totals AS (SELECT line.`Order ID` AS order_id, SUM(" + REV + ") AS total FROM `order details` line JOIN orders ord ON ord.`Order ID`=line.`Order ID` GROUP BY line.`Order ID`), ranked AS (SELECT total, ROW_NUMBER() OVER (ORDER BY total, order_id) AS position, COUNT(*) OVER () AS n FROM totals) SELECT ROUND(AVG(total),2) FROM ranked WHERE position IN (FLOOR((n+1)/2), CEIL((n+1)/2));",
   "WITH totals AS (SELECT line.`Order ID` AS order_id, SUM(" + REV + ") AS total FROM `order details` line JOIN orders ord ON ord.`Order ID`=line.`Order ID` GROUP BY line.`Order ID`) SELECT ROUND(AVG(r.total),2) FROM totals r WHERE (SELECT COUNT(*) FROM totals s WHERE (s.total, s.order_id) < (r.total, r.order_id)) IN (FLOOR(((SELECT COUNT(*) FROM totals) - 1) / 2), FLOOR((SELECT COUNT(*) FROM totals) / 2));",
   "MySQL 8.0 has no MEDIAN. Number the totals with a unique ordering (ties broken by order ID) and average the middle one (odd count) or two (even count) rows. The alternative counts how many rows sort before each row and keeps those at zero-based middle positions.",
   'computed', 'median|order total|window|percentile', 'ROW_NUMBER middle rows|row-constructor rank count'),
 S(25, "List customers with no orders from January to March 2006 but at least one order from April 2006 onwards; show customer ID and company.",
   "SELECT c.ID, c.Company FROM customers c WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.`Customer ID`=c.ID AND o.`Order Date` >= '2006-01-01' AND o.`Order Date` < '2006-04-01') AND EXISTS (SELECT 1 FROM orders o WHERE o.`Customer ID`=c.ID AND o.`Order Date` >= '2006-04-01');",
   "SELECT c.ID, c.Company FROM customers c JOIN orders o ON o.`Customer ID`=c.ID GROUP BY c.ID, c.Company HAVING SUM(o.`Order Date` >= '2006-01-01' AND o.`Order Date` < '2006-04-01') = 0 AND SUM(o.`Order Date` >= '2006-04-01') > 0;",
   "Combine an anti-existence test for the first period with an existence test for the later one. 'Afterwards' is read as 2006-04-01 or later. Customers with no orders at all fail the EXISTS part and are excluded.",
   'not_exists', 'no orders in period|later orders|anti and exists|customer', 'NOT EXISTS plus EXISTS|HAVING with period sums'),
 S(26, "List products ordered at least once from January to March 2006 and never ordered from April 2006 onwards; show product ID and name.",
   "SELECT p.ID, p.`Product Name` FROM products p WHERE EXISTS (SELECT 1 FROM `order details` l JOIN orders o ON o.`Order ID`=l.`Order ID` WHERE l.`Product ID`=p.ID AND o.`Order Date` >= '2006-01-01' AND o.`Order Date` < '2006-04-01') AND NOT EXISTS (SELECT 1 FROM `order details` l JOIN orders o ON o.`Order ID`=l.`Order ID` WHERE l.`Product ID`=p.ID AND o.`Order Date` >= '2006-04-01');",
   "SELECT p.ID, p.`Product Name` FROM products p JOIN `order details` l ON l.`Product ID`=p.ID JOIN orders o ON o.`Order ID`=l.`Order ID` GROUP BY p.ID, p.`Product Name` HAVING SUM(o.`Order Date` >= '2006-01-01' AND o.`Order Date` < '2006-04-01') > 0 AND SUM(o.`Order Date` >= '2006-04-01') = 0;",
   "Same two-period pattern on products via the order lines. Products never ordered at all are excluded (the first condition fails). NOT EXISTS is NULL-safe where NOT IN over a column that can be NULL is not.",
   'not_exists', 'ordered in period|not ordered later|anti join|product', 'EXISTS and NOT EXISTS|HAVING with period sums'),
 S(27, "Find customers whose orders were handled by more than two different employees; show customer ID and the number of employees.",
   "SELECT `Customer ID`, COUNT(DISTINCT `Employee ID`) FROM orders WHERE `Customer ID` IS NOT NULL GROUP BY `Customer ID` HAVING COUNT(DISTINCT `Employee ID`) > 2;",
   "SELECT x.customer_id, x.n FROM (SELECT d.`Customer ID` AS customer_id, COUNT(*) AS n FROM (SELECT DISTINCT `Customer ID`, `Employee ID` FROM orders WHERE `Customer ID` IS NOT NULL AND `Employee ID` IS NOT NULL) d GROUP BY d.`Customer ID`) x WHERE x.n > 2;",
   "'More than two' is strictly greater than 2 (at least three); 'at least two' would be >= 2. Distinct employees, not orders, are counted. The alternative first deduplicates (customer, employee) pairs, then counts them.",
   'group_having', 'more than n distinct|customer|employee|having', 'HAVING COUNT DISTINCT|distinct pairs then count'),
 S(28, "List customers whose orders were shipped to more than one distinct Ship City; show customer ID and company.",
   "SELECT c.ID, c.Company FROM customers c JOIN orders o ON o.`Customer ID`=c.ID GROUP BY c.ID, c.Company HAVING COUNT(DISTINCT o.`Ship City`) > 1;",
   "SELECT c.ID, c.Company FROM customers c WHERE EXISTS (SELECT 1 FROM orders a JOIN orders b ON b.`Customer ID`=a.`Customer ID` AND b.`Ship City` <> a.`Ship City` WHERE a.`Customer ID`=c.ID);",
   "Ship City varies per order, unlike the customer's own City. Orders with a NULL Ship City are ignored by both forms. The same shape answers 'more than one country' with Ship Country/Region; in this dump every order ships to one country, so that variant is empty.",
   'group_having', 'distinct ship cities|more than one|customer|having', 'HAVING COUNT DISTINCT|EXISTS self join on difference'),
 S(29, "List customers located in the same city as at least one employee; each customer once, with ID, company and city.",
   "SELECT c.ID, c.Company, c.City FROM customers c WHERE EXISTS (SELECT 1 FROM employees e WHERE e.City = c.City);",
   "SELECT DISTINCT c.ID, c.Company, c.City FROM customers c JOIN employees e ON e.City = c.City;",
   "A plain join would repeat a customer once per matching employee; EXISTS (or DISTINCT) returns each customer once. City equality follows the column collation (case-insensitive here). Swap employees for suppliers to ask the same about suppliers; no customer shares a city with a supplier in this dump.",
   'exists', 'same city|customer|employee|semi join', 'correlated EXISTS|DISTINCT join'),
 S(30, "For each category return the product or products with the second highest distinct List Price, keeping ties; show category, ID, name and List Price.",
   "SELECT Category, ID, `Product Name`, `List Price` FROM (SELECT Category, ID, `Product Name`, `List Price`, DENSE_RANK() OVER (PARTITION BY Category ORDER BY `List Price` DESC) AS position FROM products WHERE `List Price` IS NOT NULL) ranked WHERE position = 2;",
   "SELECT p.Category, p.ID, p.`Product Name`, p.`List Price` FROM products p WHERE p.`List Price` = (SELECT MAX(q.`List Price`) FROM products q WHERE q.Category <=> p.Category AND q.`List Price` < (SELECT MAX(r.`List Price`) FROM products r WHERE r.Category <=> p.Category));",
   "'Second highest' is the second distinct price: DENSE_RANK makes every product at that price qualify, whereas the second row (ROW_NUMBER) would pick one arbitrary product. Categories with a single distinct price have no second highest and return nothing. NULL prices are ignored.",
   'topn_rank', 'second highest|nth highest|category|list price', 'DENSE_RANK equals 2|nested MAX below MAX'),
 S(31, "List every product whose Product Code is shared with at least one other product; show code, product ID and name.",
   "SELECT p.`Product Code`, p.ID, p.`Product Name` FROM products p JOIN (SELECT `Product Code` FROM products GROUP BY `Product Code` HAVING COUNT(*) > 1) d ON d.`Product Code` = p.`Product Code`;",
   "SELECT p.`Product Code`, p.ID, p.`Product Name` FROM products p WHERE EXISTS (SELECT 1 FROM products q WHERE q.`Product Code` = p.`Product Code` AND q.ID <> p.ID);",
   "Finding duplicates is a GROUP BY ... HAVING COUNT(*) > 1 on the key, joined back to show the full rows. NULL codes are never equal to each other, so they are not reported as duplicates by either form.",
   'self_join', 'duplicate rows|product code|having count|self join', 'GROUP BY HAVING joined back|EXISTS other row'),
 S(32, "For each product category return one row with all its product names in alphabetical order separated by ', '.",
   "SELECT Category, GROUP_CONCAT(`Product Name` ORDER BY `Product Name`, ID SEPARATOR ', ') FROM products GROUP BY Category;",
   "WITH RECURSIVE ordered AS (SELECT Category, `Product Name` AS name, ROW_NUMBER() OVER (PARTITION BY Category ORDER BY `Product Name`, ID) AS position FROM products), joined AS (SELECT Category, position, CAST(name AS CHAR(4000)) AS names FROM ordered WHERE position = 1 UNION ALL SELECT o.Category, o.position, CONCAT(j.names, ', ', o.name) FROM joined j JOIN ordered o ON o.Category = j.Category AND o.position = j.position + 1) SELECT j.Category, j.names FROM joined j WHERE j.position = (SELECT MAX(x.position) FROM ordered x WHERE x.Category = j.Category);",
   "GROUP_CONCAT ignores NULL names and silently truncates at group_concat_max_len (1024 bytes by default). The recursive alternative builds the same string one name at a time, showing what the aggregate hides; use GROUP_CONCAT in practice.",
   'string_funcs', 'group_concat|string aggregation|category|separator', 'GROUP_CONCAT ORDER BY|recursive CTE concatenation'),
 S(33, "Split products that have a List Price into four price groups of nearly equal size with the cheapest group numbered 1, breaking price ties by product ID; show ID, name, List Price and group number.",
   "SELECT ID, `Product Name`, `List Price`, NTILE(4) OVER (ORDER BY `List Price`, ID) FROM products WHERE `List Price` IS NOT NULL;",
   "WITH numbered AS (SELECT ID, `Product Name`, `List Price`, ROW_NUMBER() OVER (ORDER BY `List Price`, ID) AS rn, COUNT(*) OVER () AS n FROM products WHERE `List Price` IS NOT NULL) SELECT ID, `Product Name`, `List Price`, CASE WHEN rn <= (n MOD 4) * (n DIV 4 + 1) THEN CEIL(rn / (n DIV 4 + 1)) ELSE (n MOD 4) + CEIL((rn - (n MOD 4) * (n DIV 4 + 1)) / (n DIV 4)) END FROM numbered;",
   "NTILE(4) gives the first n MOD 4 groups one extra row when the count does not divide evenly (45 rows: 12, 11, 11, 11). Without the ID tie-break, equal prices could land in different groups in an undefined way. The alternative reproduces the distribution rule by hand from the row number.",
   'topn_rank', 'ntile|quartile|price groups|buckets', 'NTILE window|manual bucket arithmetic'),
 S(34, "For each purchase order show the ordered quantity, the quantity on lines that have a Date Received, and flag it 'SHORT' when received is less than ordered, otherwise 'OK'; include orders without lines.",
   "SELECT p.`Purchase Order ID`, COALESCE(SUM(d.Quantity),0) AS ordered, COALESCE(SUM(CASE WHEN d.`Date Received` IS NOT NULL THEN d.Quantity END),0) AS received, CASE WHEN COALESCE(SUM(CASE WHEN d.`Date Received` IS NOT NULL THEN d.Quantity END),0) < COALESCE(SUM(d.Quantity),0) THEN 'SHORT' ELSE 'OK' END FROM `purchase orders` p LEFT JOIN `purchase order details` d ON d.`Purchase Order ID`=p.`Purchase Order ID` GROUP BY p.`Purchase Order ID`;",
   "SELECT x.id, x.ordered, x.received, IF(x.received < x.ordered, 'SHORT', 'OK') FROM (SELECT p.`Purchase Order ID` AS id, COALESCE((SELECT SUM(d.Quantity) FROM `purchase order details` d WHERE d.`Purchase Order ID`=p.`Purchase Order ID`),0) AS ordered, COALESCE((SELECT SUM(d.Quantity) FROM `purchase order details` d WHERE d.`Purchase Order ID`=p.`Purchase Order ID` AND d.`Date Received` IS NOT NULL),0) AS received FROM `purchase orders` p) x;",
   "A line counts as received when Date Received is not NULL (the ledger posting flag is not used). Orders without lines show 0 and 0 and are 'OK', not short. Use the same conditional-sum shape for any 'delivered vs requested' report.",
   'cond_agg', 'ordered vs received|purchase order|shortfall|flag', 'conditional SUM with CASE flag|correlated scalar sums'),
 S(35, "Find the customer or customers whose most recent order is older than the most recent order of every other customer (the earliest of the latest order dates); keep ties and show customer ID and that date.",
   "WITH latest AS (SELECT `Customer ID` AS customer_id, MAX(`Order Date`) AS last_order FROM orders WHERE `Customer ID` IS NOT NULL GROUP BY `Customer ID`) SELECT customer_id, last_order FROM latest WHERE last_order = (SELECT MIN(last_order) FROM latest);",
   "WITH latest AS (SELECT `Customer ID` AS customer_id, MAX(`Order Date`) AS last_order FROM orders WHERE `Customer ID` IS NOT NULL GROUP BY `Customer ID`) SELECT customer_id, last_order FROM (SELECT latest.*, RANK() OVER (ORDER BY last_order) AS position FROM latest) x WHERE position = 1;",
   "An aggregate of an aggregate: first MAX per customer, then MIN over those maxima. Customers without orders have no latest order and are not candidates. All customers tied at the oldest latest date are returned.",
   'multi_agg', 'min of max|latest order|customer|nested aggregate', 'MIN over per-customer MAX|RANK ascending'),
 S(36, "List order lines whose charged Unit Price differs from the product's current List Price, treating a NULL on one side only as different; show line ID, order ID, charged price and list price.",
   "SELECT l.ID, l.`Order ID`, l.`Unit Price`, p.`List Price` FROM `order details` l JOIN products p ON p.ID = l.`Product ID` WHERE NOT (l.`Unit Price` <=> p.`List Price`);",
   "SELECT l.ID, l.`Order ID`, l.`Unit Price`, p.`List Price` FROM `order details` l JOIN products p ON p.ID = l.`Product ID` WHERE CASE WHEN l.`Unit Price` IS NULL AND p.`List Price` IS NULL THEN 0 WHEN l.`Unit Price` IS NULL OR p.`List Price` IS NULL THEN 1 ELSE l.`Unit Price` <> p.`List Price` END = 1;",
   "NOT (a <=> b) is the NULL-safe 'differs'; plain <> drops rows where either side is NULL. EMPTY RESULT in this dump: every Unit Price equals the product List Price, so the query returns no rows but is the correct pattern.",
   'null_handling', 'price differs|unit price vs list price|null safe comparison', 'NULL-safe inequality|explicit NULL branch'),
 S(37, "List every calendar week (Monday start) from 2006-01-02 to 2006-06-26 with its number of orders, including weeks without orders; show the week start date.",
   "WITH RECURSIVE weeks AS (SELECT DATE '2006-01-02' AS week_start UNION ALL SELECT week_start + INTERVAL 7 DAY FROM weeks WHERE week_start < DATE '2006-06-26') SELECT w.week_start, COUNT(o.`Order ID`) FROM weeks w LEFT JOIN orders o ON o.`Order Date` >= w.week_start AND o.`Order Date` < w.week_start + INTERVAL 7 DAY GROUP BY w.week_start;",
   "WITH numbers AS (SELECT ROW_NUMBER() OVER (ORDER BY ID) - 1 AS k FROM `order details`) SELECT DATE '2006-01-02' + INTERVAL 7 * k DAY AS week_start, (SELECT COUNT(*) FROM orders o WHERE o.`Order Date` >= DATE '2006-01-02' + INTERVAL 7 * k DAY AND o.`Order Date` < DATE '2006-01-02' + INTERVAL 7 * (k + 1) DAY) FROM numbers WHERE k <= 25;",
   "To list periods that have no data, generate the calendar first (recursive CTE) and LEFT JOIN the facts onto it; grouping the facts alone can never show an empty week. The alternative borrows row numbers from a table with at least 26 rows (the ponytail shortcut: fine as a trick, not as a design).",
   'left_join', 'calendar|weeks without orders|recursive cte|left join', 'recursive calendar CTE|row-number generator'),
 S(38, "Count orders per employee and add a final grand-total row labelled 'ALL' using GROUP BY ... WITH ROLLUP.",
   "SELECT IF(GROUPING(`Employee ID`), 'ALL', `Employee ID`) AS employee, COUNT(*) FROM orders GROUP BY `Employee ID` WITH ROLLUP;",
   "SELECT CAST(`Employee ID` AS CHAR), COUNT(*) FROM orders GROUP BY `Employee ID` UNION ALL SELECT 'ALL', COUNT(*) FROM orders;",
   "WITH ROLLUP adds a super-aggregate row whose grouping column is NULL; GROUPING() tells that NULL apart from a real NULL group. The IF turns it into a label (mixing a number and a string yields a string). UNION ALL of the detail and total queries is the portable equivalent.",
   'multi_agg', 'with rollup|grand total row|grouping|union all', 'WITH ROLLUP and GROUPING|UNION ALL total row'),
 S(39, "Count orders for every day of the week, Monday first, including weekdays with no orders; show the day name and the count.",
   "WITH days AS (SELECT 0 AS d, 'Monday' AS day_name UNION ALL SELECT 1, 'Tuesday' UNION ALL SELECT 2, 'Wednesday' UNION ALL SELECT 3, 'Thursday' UNION ALL SELECT 4, 'Friday' UNION ALL SELECT 5, 'Saturday' UNION ALL SELECT 6, 'Sunday') SELECT days.day_name, COUNT(o.`Order ID`) FROM days LEFT JOIN orders o ON WEEKDAY(o.`Order Date`) = days.d GROUP BY days.d, days.day_name;",
   "WITH days (d, day_name) AS (VALUES ROW(0, 'Monday'), ROW(1, 'Tuesday'), ROW(2, 'Wednesday'), ROW(3, 'Thursday'), ROW(4, 'Friday'), ROW(5, 'Saturday'), ROW(6, 'Sunday')) SELECT day_name, (SELECT COUNT(*) FROM orders o WHERE WEEKDAY(o.`Order Date`) = days.d) FROM days;",
   "WEEKDAY() numbers Monday as 0 (DAYOFWEEK starts at Sunday = 1), so the helper table is keyed on WEEKDAY. A literal list of days is the dimension table; LEFT JOIN keeps days with zero orders. VALUES ROW needs MySQL 8.0.19 or later (fine on 8.0.28).",
   'left_join', 'weekday|day of week|orders per weekday|zero days', 'literal day table LEFT JOIN|VALUES ROW with scalar counts'),
 S(40, "Which employee or employees have the highest average discounted order total (the average of their per-order totals)? Keep ties; show employee ID and the average rounded to cents.",
   "WITH " + ORDER_TOTALS + ", averages AS (SELECT employee_id, AVG(total) AS average_total FROM order_totals WHERE employee_id IS NOT NULL GROUP BY employee_id) SELECT employee_id, ROUND(average_total,2) FROM averages WHERE average_total = (SELECT MAX(average_total) FROM averages);",
   "WITH " + ORDER_TOTALS + " SELECT employee_id, ROUND(average_total,2) FROM (SELECT employee_id, AVG(total) AS average_total, RANK() OVER (ORDER BY AVG(total) DESC) AS position FROM order_totals WHERE employee_id IS NOT NULL GROUP BY employee_id) x WHERE position = 1;",
   "Average order value = mean of order totals per employee, which differs from total revenue (rewards few large orders, not volume). Aggregate in two steps, then take the maximum with ties kept.",
   'multi_agg', 'highest average|order value|employee|nested aggregate', 'AVG of SUM then MAX|RANK over AVG'),
 S(41, "List pairs of different orders placed by the same customer on the same Order Date, each pair once (smaller Order ID first); show customer ID, both order IDs and the date.",
   "SELECT a.`Customer ID`, a.`Order ID`, b.`Order ID`, a.`Order Date` FROM orders a JOIN orders b ON b.`Customer ID` = a.`Customer ID` AND b.`Order Date` = a.`Order Date` AND b.`Order ID` > a.`Order ID`;",
   "WITH same_day AS (SELECT `Customer ID`, `Order Date` FROM orders WHERE `Customer ID` IS NOT NULL GROUP BY `Customer ID`, `Order Date` HAVING COUNT(*) > 1) SELECT s.`Customer ID`, a.`Order ID`, b.`Order ID`, s.`Order Date` FROM same_day s JOIN orders a ON a.`Customer ID` = s.`Customer ID` AND a.`Order Date` = s.`Order Date` JOIN orders b ON b.`Customer ID` = s.`Customer ID` AND b.`Order Date` = s.`Order Date` AND b.`Order ID` > a.`Order ID`;",
   "Joining a table to itself with b.ID > a.ID returns every unordered pair once and never pairs a row with itself; <> would give each pair twice. The alternative first finds the (customer, date) groups with more than one order.",
   'self_join', 'pairs|same day|self join|duplicate pairs', 'self join with ID inequality|duplicate groups then self join'),
 S(42, "Classify each order by its discounted total into Small (below 500), Medium (500 up to but not including 1500) and Large (1500 and above) and count orders per band; show all three bands even when a band is empty.",
   "WITH totals AS (SELECT line.`Order ID` AS order_id, SUM(" + REV + ") AS total FROM `order details` line JOIN orders ord ON ord.`Order ID`=line.`Order ID` GROUP BY line.`Order ID`), bands (band, low, high) AS (VALUES ROW('Small', 0, 500), ROW('Medium', 500, 1500), ROW('Large', 1500, 1000000000)) SELECT b.band, COUNT(t.order_id) FROM bands b LEFT JOIN totals t ON t.total >= b.low AND t.total < b.high GROUP BY b.band;",
   "WITH totals AS (SELECT line.`Order ID` AS order_id, SUM(" + REV + ") AS total FROM `order details` line JOIN orders ord ON ord.`Order ID`=line.`Order ID` GROUP BY line.`Order ID`) SELECT 'Small', COUNT(*) FROM totals WHERE total < 500 UNION ALL SELECT 'Medium', COUNT(*) FROM totals WHERE total >= 500 AND total < 1500 UNION ALL SELECT 'Large', COUNT(*) FROM totals WHERE total >= 1500;",
   "Half-open ranges [low, high) keep every boundary value in exactly one band. A CASE expression grouped by band would silently omit empty bands; a band table with a LEFT JOIN (or one COUNT per band) shows zeros. Orders without lines have no total and are not classified.",
   'cond_agg', 'bands|histogram|case classification|order total', 'band table LEFT JOIN|UNION ALL per band'),
 S(43, "List orders placed within the 30 days up to and including the latest Order Date in the table (do not use the current date); show order ID and order date.",
   "SELECT `Order ID`, `Order Date` FROM orders WHERE `Order Date` > DATE_SUB((SELECT MAX(`Order Date`) FROM orders), INTERVAL 30 DAY);",
   "SELECT o.`Order ID`, o.`Order Date` FROM orders o JOIN (SELECT MAX(`Order Date`) AS last_day FROM orders) m ON o.`Order Date` > m.last_day - INTERVAL 30 DAY;",
   "'Last 30 days' is anchored on the newest order, not NOW(): the data is historical, so the current date would return nothing. The window is the latest date and the 29 days before it (30 calendar days). The alternative joins to a one-row derived table holding the latest date; both compare the bare column to a computed bound, which keeps an index on Order Date usable.",
   'date', 'last 30 days|relative to latest date|date window|max date', 'range from MAX date|DATEDIFF to MAX date'),
 S(44, "List customers whose total discounted spending is higher than the average spending of customers in the same State/Province, averaging over customers with sales; show customer ID, state and spending.",
   "WITH spend AS (SELECT c.ID AS customer_id, c.`State/Province` AS state, SUM(" + REV + ") AS total FROM customers c JOIN orders ord ON ord.`Customer ID`=c.ID JOIN `order details` line ON line.`Order ID`=ord.`Order ID` GROUP BY c.ID, c.`State/Province`) SELECT customer_id, state, ROUND(total,2) FROM (SELECT spend.*, AVG(total) OVER (PARTITION BY state) AS state_average FROM spend) x WHERE total > state_average;",
   "WITH spend AS (SELECT c.ID AS customer_id, c.`State/Province` AS state, SUM(" + REV + ") AS total FROM customers c JOIN orders ord ON ord.`Customer ID`=c.ID JOIN `order details` line ON line.`Order ID`=ord.`Order ID` GROUP BY c.ID, c.`State/Province`) SELECT s.customer_id, s.state, ROUND(s.total,2) FROM spend s WHERE s.total > (SELECT AVG(t.total) FROM spend t WHERE t.state <=> s.state);",
   "Compare each row to an aggregate of its own group: a partitioned window average or a correlated scalar subquery. A state with a single active customer can never be above its own average. Strictly greater, so equal spenders are excluded.",
   'correlated', 'above group average|state|customer spending|correlated', 'AVG partition window|correlated group average'),
 S(45, "List orders that contain products from at least two different categories; return the order IDs.",
   "SELECT l.`Order ID` FROM `order details` l JOIN products p ON p.ID = l.`Product ID` GROUP BY l.`Order ID` HAVING COUNT(DISTINCT p.Category) >= 2;",
   "SELECT DISTINCT a.`Order ID` FROM `order details` a JOIN products pa ON pa.ID = a.`Product ID` JOIN `order details` b ON b.`Order ID` = a.`Order ID` JOIN products pb ON pb.ID = b.`Product ID` WHERE pa.Category <> pb.Category;",
   "COUNT(DISTINCT category) per order is the direct answer; the alternative looks for two lines of one order whose categories differ (DISTINCT removes the repeated pairs). Products with a NULL category are ignored by both.",
   'group_having', 'distinct categories per order|at least two|having count distinct', 'HAVING COUNT DISTINCT|self join on differing category'),
 S(46, "For each customer find the employee or employees who handled the most of that customer's orders; keep ties and show customer ID, employee ID and the order count.",
   "WITH counts AS (SELECT `Customer ID` AS customer_id, `Employee ID` AS employee_id, COUNT(*) AS n FROM orders WHERE `Customer ID` IS NOT NULL AND `Employee ID` IS NOT NULL GROUP BY `Customer ID`, `Employee ID`) SELECT customer_id, employee_id, n FROM (SELECT counts.*, RANK() OVER (PARTITION BY customer_id ORDER BY n DESC) AS position FROM counts) x WHERE position = 1;",
   "WITH counts AS (SELECT `Customer ID` AS customer_id, `Employee ID` AS employee_id, COUNT(*) AS n FROM orders WHERE `Customer ID` IS NOT NULL AND `Employee ID` IS NOT NULL GROUP BY `Customer ID`, `Employee ID`) SELECT c.customer_id, c.employee_id, c.n FROM counts c WHERE c.n = (SELECT MAX(d.n) FROM counts d WHERE d.customer_id = c.customer_id);",
   "Group by the pair (customer, employee) first, then pick the maximum per customer; RANK = 1 (or equality to a correlated MAX) keeps every employee tied at the top, which a LIMIT 1 per customer could not.",
   'topn_rank', 'most frequent per group|customer|employee|ties', 'RANK per customer|correlated MAX per customer'),
 S(47, "List employees who placed at least one order in every month in which any order was placed; show the employee ID.",
   "SELECT `Employee ID` FROM orders WHERE `Employee ID` IS NOT NULL GROUP BY `Employee ID` HAVING COUNT(DISTINCT DATE_FORMAT(`Order Date`,'%Y-%m')) = (SELECT COUNT(DISTINCT DATE_FORMAT(`Order Date`,'%Y-%m')) FROM orders);",
   "SELECT e.ID FROM employees e WHERE NOT EXISTS (SELECT 1 FROM orders m WHERE NOT EXISTS (SELECT 1 FROM orders x WHERE x.`Employee ID` = e.ID AND DATE_FORMAT(x.`Order Date`,'%Y-%m') = DATE_FORMAT(m.`Order Date`,'%Y-%m')));",
   "Relational division over time: every month that exists must be matched by one of the employee's orders. The counting form compares distinct months; the double NOT EXISTS says 'there is no month without an order of this employee'. Employees without orders qualify only if no month exists at all.",
   'division', 'every month|relational division|employee|double not exists', 'distinct month count equals total|double NOT EXISTS'),
 D(48, "Add a new shipper with ID 4 and Company 'Shipping Company D' to the shippers table.",
   "INSERT INTO shippers (ID, Company) VALUES (4, 'Shipping Company D');",
   "INSERT INTO shippers SET ID = 4, Company = 'Shipping Company D';",
   "SELECT ID, Company FROM shippers ORDER BY ID;", None, 'rollback',
   "Name the columns in INSERT so the statement survives column reordering; unlisted columns get NULL or their default (partial row). ID has no AUTO_INCREMENT here, so it must be supplied; a duplicate ID would fail with error 1062.",
   'select_filter', 'insert|new row|partial row|shippers', 'INSERT VALUES|INSERT SET'),
 D(49, "Raise the List Price of all products in the Beverages category by ten percent.",
   "UPDATE products SET `List Price` = `List Price` * 1.10 WHERE Category = 'Beverages';",
   "UPDATE products p JOIN (SELECT ID FROM products WHERE Category = 'Beverages') b ON b.ID = p.ID SET p.`List Price` = p.`List Price` + p.`List Price` * 0.10;",
   "SELECT ID, `List Price` FROM products WHERE Category = 'Beverages' ORDER BY ID;", None, 'rollback',
   "Always keep the WHERE clause: without it every product is updated. The right-hand side uses the old value of the column. NULL prices stay NULL. Preview with the same WHERE in a SELECT first and run inside a transaction when possible.",
   'computed', 'update|percentage increase|where clause|category', 'UPDATE with arithmetic|UPDATE join derived table'),
 D(50, "Delete customers who have never placed an order.",
   "DELETE FROM customers WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.`Customer ID` = customers.ID);",
   "DELETE c FROM customers c LEFT JOIN orders o ON o.`Customer ID` = c.ID WHERE o.`Order ID` IS NULL;",
   "SELECT ID FROM customers ORDER BY ID;", None, 'rollback',
   "Anti-join DELETE: NOT EXISTS (or LEFT JOIN ... IS NULL) is safe; NOT IN breaks if the subquery column contains NULL (it deletes nothing). Run the SELECT with the same condition first. There are no foreign keys in this dump, so nothing stops the delete; with FKs the ON DELETE rule would apply.",
   'not_exists', 'delete|customers without orders|anti join|cleanup', 'DELETE with NOT EXISTS|DELETE JOIN anti join'),
 D(51, "Mark as Discontinued (set Discontinued to 1) every product that has never been ordered.",
   "UPDATE products SET Discontinued = 1 WHERE NOT EXISTS (SELECT 1 FROM `order details` l WHERE l.`Product ID` = products.ID);",
   "UPDATE products p LEFT JOIN `order details` l ON l.`Product ID` = p.ID SET p.Discontinued = 1 WHERE l.ID IS NULL;",
   "SELECT ID, Discontinued FROM products ORDER BY ID;", None, 'rollback',
   "UPDATE with a subquery condition: the subquery may read another table freely but not the table being updated (error 1093 unless wrapped in a derived table). Use NOT EXISTS rather than NOT IN so a NULL Product ID cannot block the update.",
   'not_exists', 'update with subquery|never ordered|discontinued', 'UPDATE with NOT EXISTS|UPDATE LEFT JOIN'),
 D(52, "Insert the shippers (1, 'Renamed Co') and (4, 'New Co'): update the Company if the ID already exists, otherwise insert a new row (an upsert).",
   "INSERT INTO shippers (ID, Company) VALUES (1, 'Renamed Co'), (4, 'New Co') AS new_row ON DUPLICATE KEY UPDATE Company = new_row.Company;",
   "UPDATE shippers SET Company = 'Renamed Co' WHERE ID = 1; INSERT INTO shippers (ID, Company) SELECT 4, 'New Co' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM shippers WHERE ID = 4);",
   "SELECT ID, Company FROM shippers ORDER BY ID;", None, 'rollback',
   "ON DUPLICATE KEY UPDATE fires when the primary or a unique key already exists and keeps the other columns of the existing row. REPLACE INTO would delete and re-insert the row, resetting unlisted columns to defaults. The AS alias form needs MySQL 8.0.19+; older code uses VALUES(Company).",
   'select_filter', 'upsert|on duplicate key update|insert or update|replace', 'ON DUPLICATE KEY UPDATE|UPDATE plus guarded INSERT'),
 D(53, "Remove duplicate products that share a Product Code, keeping the product with the smallest ID for each code.",
   "DELETE p FROM products p JOIN products q ON q.`Product Code` = p.`Product Code` AND q.ID < p.ID;",
   "DELETE FROM products WHERE ID NOT IN (SELECT keep_id FROM (SELECT MIN(ID) AS keep_id FROM products GROUP BY `Product Code`) k);",
   "SELECT ID, `Product Code` FROM products ORDER BY ID;", None, 'rollback',
   "Self-join DELETE removes every row that has a smaller-ID twin. The NOT IN form needs a derived table (MySQL rejects selecting from the table being deleted from) and is only safe because keep_id is never NULL. Rows with a NULL Product Code never match the join, so they are never deleted by the first form.",
   'self_join', 'delete duplicates|keep smallest id|product code|self join delete', 'DELETE self join|DELETE NOT IN of MIN per group'),
 D(54, "Create a table orders_archive containing all orders placed before March 2006.",
   "CREATE TABLE orders_archive AS SELECT * FROM orders WHERE `Order Date` < '2006-03-01';",
   "CREATE TABLE orders_archive LIKE orders; INSERT INTO orders_archive SELECT * FROM orders WHERE `Order Date` < '2006-03-01';",
   "SELECT COUNT(*), MIN(`Order ID`), MAX(`Order ID`) FROM orders_archive;", "DROP TABLE IF EXISTS orders_archive;", 'ddl',
   "CREATE TABLE ... AS SELECT copies columns and rows but not the primary key, indexes or AUTO_INCREMENT; CREATE TABLE ... LIKE copies the full structure but no rows, so a following INSERT ... SELECT fills it. DDL commits immediately and cannot be rolled back.",
   'select_filter', 'create table as select|archive|ctas|create table like', 'CREATE TABLE AS SELECT|CREATE LIKE then INSERT SELECT'),
 D(55, "Create a view customer_spend that shows each customer's ID, company and total discounted spending rounded to cents, for customers with orders.",
   "CREATE VIEW customer_spend AS SELECT c.ID, c.Company, ROUND(SUM(line.Quantity*line.`Unit Price`*(1-line.Discount)),2) AS total FROM customers c JOIN orders ord ON ord.`Customer ID` = c.ID JOIN `order details` line ON line.`Order ID` = ord.`Order ID` GROUP BY c.ID, c.Company;",
   "CREATE VIEW customer_spend AS SELECT c.ID, c.Company, (SELECT ROUND(SUM(l.Quantity*l.`Unit Price`*(1-l.Discount)),2) FROM orders o JOIN `order details` l ON l.`Order ID` = o.`Order ID` WHERE o.`Customer ID` = c.ID) AS total FROM customers c WHERE EXISTS (SELECT 1 FROM orders o JOIN `order details` l ON l.`Order ID` = o.`Order ID` WHERE o.`Customer ID` = c.ID);",
   "SELECT ID, Company, total FROM customer_spend ORDER BY ID;", "DROP VIEW IF EXISTS customer_spend;", 'ddl',
   "A view stores a query, not data: every SELECT re-runs it. A view with GROUP BY is not updatable. Dropping the view does not touch the base tables. Query it like a table once created.",
   'inner_join', 'create view|view definition|customer spending|virtual table', 'CREATE VIEW grouped join|CREATE VIEW correlated subquery'),
 D(56, "Add a column Active (TINYINT(1), NOT NULL, default 1) to the shippers table.",
   "ALTER TABLE shippers ADD COLUMN Active TINYINT(1) NOT NULL DEFAULT 1;",
   "ALTER TABLE shippers ADD COLUMN Active TINYINT(1) NULL; UPDATE shippers SET Active = 1; ALTER TABLE shippers MODIFY Active TINYINT(1) NOT NULL DEFAULT 1;",
   "SELECT ID, Active FROM shippers ORDER BY ID;", "ALTER TABLE shippers DROP COLUMN Active;", 'ddl',
   "With NOT NULL plus DEFAULT, MySQL fills existing rows with the default in one step. Adding NOT NULL without a default to a populated table fails or fills implicit zeros depending on sql_mode, hence the safe three-step alternative. ALTER TABLE is DDL: it commits and cannot be rolled back.",
   'select_filter', 'alter table|add column|not null default', 'ALTER ADD COLUMN NOT NULL DEFAULT|add nullable, backfill, tighten'),
 D(57, "Create an index on orders covering Customer ID and then Order Date.",
   "CREATE INDEX idx_orders_customer_date ON orders (`Customer ID`, `Order Date`);",
   "ALTER TABLE orders ADD INDEX idx_orders_customer_date (`Customer ID`, `Order Date`);",
   "SELECT INDEX_NAME, SEQ_IN_INDEX, COLUMN_NAME FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'orders' AND INDEX_NAME = 'idx_orders_customer_date' ORDER BY SEQ_IN_INDEX;", "DROP INDEX idx_orders_customer_date ON orders;", 'ddl',
   "Column order matters in a composite index: this one serves filters on Customer ID alone or Customer ID plus Order Date (leftmost prefix), not Order Date alone. CREATE INDEX and ALTER TABLE ... ADD INDEX are equivalent. Every extra index slows INSERT/UPDATE.",
   'optimization', 'create index|composite index|leftmost prefix|ddl', 'CREATE INDEX|ALTER TABLE ADD INDEX'),
]
